using System;
using System.IO;
using System.Text.Json;
using System.Linq;
using System.Diagnostics;
using CelestialMaker.Core;
using BreakInfinity;
class Program {
 static JsonSerializerOptions json=new JsonSerializerOptions{IncludeFields=true};static Content data;static int pass,fail;
 static void Check(string name,bool ok){Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(ok)pass++;else fail++;}
 static void Advance(Simulation sim,double elapsed){double pending=elapsed;int rounds=0;while(pending>1e-6&&rounds++<256)pending=sim.Advance(pending);if(pending>1e-6)throw new Exception("Event budget exhausted");}
 static void Main(string[] args){System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.InvariantCulture;string root=args[0];data=JsonSerializer.Deserialize<Content>(File.ReadAllText(Path.Combine(root,"Game/Assets/_CelestialMaker/Resources/content.json")),json);
  if(args.Contains("--offline")){OfflineTests.Run(data,json,Check,root);File.WriteAllText(Path.Combine(root,"Logs/offline-tests.json"),JsonSerializer.Serialize(new{pass,fail}));Environment.ExitCode=fail==0?0:1;return;}
  Check("content counts",data.generators.Length==24&&data.upgrades.Length==60&&data.research.Length==30&&data.talents.Length==24&&data.challenges.Length==12&&data.achievements.Length==48&&data.expeditions.Length==8&&data.stories.Length==12);
  var huge=new Number(BigDouble.Parse("1e10000"));var round=JsonSerializer.Deserialize<Number>(JsonSerializer.Serialize(huge,json),json);Check("1e10000 serialization",round.Value==huge.Value);Check("1e10000 arithmetic",BigDouble.Log10(huge.Value*huge.Value)==20000);
  var a=new Simulation(data);Advance(a,75);Check("passive initial income",a.S.resources[0].Value>10);Check("first purchase",a.Buy(1,1));Advance(a,100);Check("particle production and nonnegative resources",a.S.resources[1].Value>0&&a.S.resources.All(x=>x.Value>=0));
  var state=JsonSerializer.Serialize(a.S,json);var original=JsonSerializer.Deserialize<State>(state,json);var b=new Simulation(data,JsonSerializer.Deserialize<State>(state,json));Advance(a,86400);for(int i=0;i<8640;i++)Advance(b,10);double err=Enumerable.Range(0,12).Max(i=>Relative(a.S.resources[i].Value,b.S.resources[i].Value));Check("24h online/offline relative error <0.5%",err<.005);Console.WriteLine("offlineRelativeError="+err);
  foreach(double duration in new[]{3600d,86400d,604800d,2592000d,31536000d}){var s=new Simulation(data,JsonSerializer.Deserialize<State>(JsonSerializer.Serialize(original,json),json));var sw=Stopwatch.StartNew();Advance(s,duration);Check("offline "+duration+" seconds",s.S.resources.All(x=>x.Value>=0)&&Math.Abs(s.S.time-original.time-duration)<.01);Console.WriteLine("offlineMs="+sw.Elapsed.TotalMilliseconds);}
  var max=new Simulation(data);max.S.resources[0]=BigDouble.Parse("1e10000");long n=max.MaxBuy(0);Check("Max Buy affordable",n>0&&max.Cost(0,n)<=max.S.resources[0].Value);Check("Max Buy next unaffordable",max.Cost(0,n+1)>max.S.resources[0].Value);max.Buy(0,n);Check("bulk buy nonnegative",max.S.resources[0].Value>=0);
  var boost=new Simulation(data);boost.PremiumUntil=50;var noBoost=new Simulation(data);Advance(boost,100);Advance(noBoost,100);Check("boost expires mid offline",boost.S.resources[0].Value>noBoost.S.resources[0].Value&&boost.S.resources[0].Value<noBoost.S.resources[0].Value*2);
  var prestige=new Simulation(data);prestige.S.lifetime[0]=BigDouble.Parse("1e9");Check("prestige",prestige.Rebirth(0)&&prestige.S.resets[0]==1&&prestige.S.owned[0]==1);prestige.S.lifetime[6]=BigDouble.Parse("1e15");prestige.Rebirth(1);prestige.S.lifetime[11]=BigDouble.Parse("1e21");Check("three prestige layers",prestige.Rebirth(2)&&prestige.S.resets[2]==1);
  var voyage=new Simulation(data);voyage.S.resets[1]=1;voyage.S.resources[0]=BigDouble.Parse("1e8");Check("expedition launch",voyage.StartVoyage(0));Advance(voyage,301);var v=voyage.S.voyages[0];Check("claim exactly once",voyage.Claim(v)&&!voyage.Claim(v));
  var challenge=new Simulation(data);challenge.S.resets[0]=1;var before=challenge.S.resources[0].Value;Check("enter challenge",challenge.EnterChallenge(0));Advance(challenge,10);challenge.ExitChallenge();Check("restore economy on challenge exit",challenge.S.resources[0].Value==before&&challenge.S.activeChallenge=="");
  var cursor=new Simulation(data);cursor.S.owned[1]=3;double left=cursor.Advance(86400,1);var resumed=new Simulation(data,JsonSerializer.Deserialize<State>(JsonSerializer.Serialize(cursor.S,json),json));Advance(resumed,left);var uninterrupted=new Simulation(data);uninterrupted.S.owned[1]=3;Advance(uninterrupted,86400);Check("offline cursor survives serialization",Enumerable.Range(0,12).All(i=>Relative(resumed.S.resources[i].Value,uninterrupted.S.resources[i].Value)<.005));var legacy=new State{version=0};Check("version 0 migration",SaveMigrations.Upgrade(legacy).version==1);var unknown=new State{version=999};bool futureRejected=false;try{new Simulation(data,unknown);}catch{futureRejected=true;}Check("unknown future schema rejected",futureRejected);
  bool rejected=false;try{var corrupt=new State();corrupt.resources[0].mantissa=double.NaN;new Simulation(data,corrupt);}catch{rejected=true;}Check("corrupt state rejected",rejected);
  var interval=new Simulation(data);interval.BoostWindows.Add(new BoostWindow{start=10,end=50});Advance(interval,100);Check("verified boost interval start and expiry",interval.S.resources[0].Value>noBoost.S.resources[0].Value&&interval.S.resources[0].Value<boost.S.resources[0].Value);var mature=JsonSerializer.Deserialize<State>(File.ReadAllText(Path.Combine(root,"Logs/late-game-fixture.json")),json);var complexA=new Simulation(data,JsonSerializer.Deserialize<State>(JsonSerializer.Serialize(mature,json),json));var complexB=new Simulation(data,JsonSerializer.Deserialize<State>(JsonSerializer.Serialize(mature,json),json));var traceA=new System.Collections.Generic.List<string>();var traceB=new System.Collections.Generic.List<string>();complexA.OnBought=(i,n,t)=>traceA.Add(i+"x"+n+"@"+t);complexB.OnBought=(i,n,t)=>traceB.Add(i+"x"+n+"@"+t);complexA.S.automation.buy=complexB.S.automation.buy=true;Advance(complexA,3600);for(int k=0;k<360;k++)Advance(complexB,10);double complexError=Enumerable.Range(0,12).Max(i=>Relative(complexA.S.resources[i].Value,complexB.S.resources[i].Value));Check("combined 24-process automation online/offline",complexError<.005&&complexA.S.owned.SequenceEqual(complexB.S.owned));Console.WriteLine("complexRelativeError="+complexError);if(complexError>=.005){Console.WriteLine("TRACE A "+string.Join("; ",traceA.Take(25)));Console.WriteLine("TRACE B "+string.Join("; ",traceB.Take(25)));Console.WriteLine("A owned="+string.Join(",",complexA.S.owned));Console.WriteLine("B owned="+string.Join(",",complexB.S.owned));for(int i=0;i<12;i++)Console.WriteLine("resource "+i+" A="+complexA.S.resources[i]+" B="+complexB.S.resources[i]);}
  OfflineTests.Run(data,json,Check,root);Policy(root);ExerciseContent(root);File.WriteAllText(Path.Combine(root,"Logs/simulator-result.json"),JsonSerializer.Serialize(new{pass,fail,offlineRelativeError=err}));Environment.ExitCode=fail==0?0:1;
 }
 static double Relative(BigDouble a,BigDouble b)=>a==b?0:a==0||b==0?1:Math.Abs((a/b).ToDouble()-1);
  static void Choices(Simulation s){int missing=Array.FindIndex(data.generators,g=>s.Open(g)&&s.S.owned[Array.IndexOf(data.generators,g)]==0);if(missing>=0){int currency=data.generators[missing].costResource;for(int k=0;k<24;k++)s.S.paused[k]=data.generators[k].input==currency;if(s.Buy(missing,1))Array.Clear(s.S.paused);for(int k=0;k<24;k++)if(data.generators[k].costResource!=currency)s.Buy(k,Math.Max(1,s.MaxBuy(k)/4));foreach(var u in data.upgrades)if(u.costResource!=currency)s.Purchase(u);foreach(var r in data.research)if(r.costResource!=currency)s.Purchase(r);}else{var goal=Array.Find(data.upgrades,u=>s.StageOpen(u.stage)&&!s.S.purchases.Contains(u.id));if(goal!=null){int currency=goal.costResource;for(int k=0;k<24;k++)s.S.paused[k]=data.generators[k].input==currency;for(int k=23;k>=0;k--)if(data.generators[k].costResource!=currency)s.Buy(k,1);if(s.Purchase(goal))Array.Clear(s.S.paused);}else{Array.Clear(s.S.paused);for(int i=23;i>=0;i--)s.Buy(i,1);}foreach(var r in data.research)s.Purchase(r);}}
 static void ExerciseContent(string root){var baseState=JsonSerializer.Deserialize<State>(File.ReadAllText(Path.Combine(root,"Logs/late-game-fixture.json")),json);var s=new Simulation(data,baseState);s.S.automation.buy=false;var start=s.S.time;int completed=0;for(int i=0;i<12;i++){bool entered=s.EnterChallenge(i);for(int tick=0;tick<14400&&s.S.activeChallenge!="";tick++){Choices(s);Advance(s,60);}bool done=entered&&s.S.completedChallenges.Contains(data.challenges[i].id);Check("challenge natural completion "+i,done);if(done)completed++;else s.ExitChallenge();}for(int i=0;i<24;i++)s.S.paused[i]=data.generators[i].input==0;for(int i=0;i<8;i++){bool launched=s.StartVoyage(i);for(int tick=0;!launched&&tick<14400;tick++){Advance(s,60);launched=s.StartVoyage(i);}Check("expedition reachable "+i,launched);}Advance(s,3600);int claims=0;foreach(var v in s.S.voyages)if(s.Claim(v))claims++;Check("all 8 expedition claims",claims==8);int talents=0;for(int tick=0;tick<43200&&talents<24;tick++){foreach(var talent in data.talents)s.Talent(talent);talents=s.S.talents.Count;if(talents==24)break;if(s.PrestigeReward(1)>=1){s.Rebirth(1);}Choices(s);Advance(s,60);}Check("all 24 talents naturally affordable",talents==24);File.WriteAllText(Path.Combine(root,"Logs/extended-content-result.json"),JsonSerializer.Serialize(new{challenges=completed,expeditionClaims=claims,talents,elapsedSimulationDays=(s.S.time-start)/86400}));}
 static void Policy(string root){var s=new Simulation(data);double first=-1,second=-1,third=-1;bool wroteFixture=false;var stagesSaved=new bool[6];Directory.CreateDirectory(Path.Combine(root,"Logs/StageFixtures"));var seen=new System.Collections.Generic.HashSet<string>();var rows=new System.Collections.Generic.List<string>{"seconds,stage,stellar,galactic,universal,energyLog"};for(int tick=0;tick<30*24*60;tick++){int missing=Array.FindIndex(data.generators,g=>s.Open(g)&&s.S.owned[Array.IndexOf(data.generators,g)]==0);if(missing>=0){int currency=data.generators[missing].costResource;for(int k=0;k<24;k++)s.S.paused[k]=data.generators[k].input==currency;if(s.Buy(missing,1))Array.Clear(s.S.paused);for(int k=0;k<24;k++)if(data.generators[k].costResource!=currency)s.Buy(k,Math.Max(1,s.MaxBuy(k)/4));foreach(var u in data.upgrades)if(u.costResource!=currency)s.Purchase(u);foreach(var r in data.research)if(r.costResource!=currency)s.Purchase(r);}else{var goal=Array.Find(data.upgrades,u=>s.StageOpen(u.stage)&&!s.S.purchases.Contains(u.id));if(goal!=null){int currency=goal.costResource;for(int k=0;k<24;k++)s.S.paused[k]=data.generators[k].input==currency;for(int k=23;k>=0;k--)if(data.generators[k].costResource!=currency)s.Buy(k,1);if(s.Purchase(goal))Array.Clear(s.S.paused);}else{Array.Clear(s.S.paused);for(int i=23;i>=0;i--)s.Buy(i,1);}foreach(var r in data.research)s.Purchase(r);}for(int i=0;i<24;i++)if(s.S.owned[i]>0)seen.Add(data.generators[i].id);foreach(var purchase in s.S.purchases)seen.Add(purchase);if(s.S.owned.All(n=>n>0)&&!wroteFixture){File.WriteAllText(Path.Combine(root,"Logs/late-game-fixture.json"),JsonSerializer.Serialize(s.S,json));wroteFixture=true;}for(int stage=0;stage<6;stage++)if(s.StageOpen(stage)&&!stagesSaved[stage]){stagesSaved[stage]=true;File.WriteAllText(Path.Combine(root,"Logs/StageFixtures/stage-"+stage+".json"),JsonSerializer.Serialize(s.S,json));}for(int i=2;i>=0;i--)if((i!=2||third<0&&s.S.owned.All(n=>n>0)||third>=0&&s.S.purchases.Count>=data.upgrades.Length+data.research.Length)&&s.PrestigeReward(i)>=1&&((i==0&&first<0)||(i==1&&second<0)||i==2)){s.Rebirth(i);if(i==0&&first<0)first=s.S.time;if(i==1&&second<0)second=s.S.time;if(i==2&&third<0)third=s.S.time;}Advance(s,60);if(tick%60==0)rows.Add(s.S.time+","+Enumerable.Range(0,6).Count(i=>s.StageOpen(i))+","+s.S.resets[0]+","+s.S.resets[1]+","+s.S.resets[2]+","+BigDouble.Log10(s.S.lifetime[0].Value));}File.WriteAllLines(Path.Combine(root,"Logs/progression.csv"),rows);File.WriteAllText(Path.Combine(root,"Logs/policy-state.json"),JsonSerializer.Serialize(s.S,json));Console.WriteLine("CONTENT everGenerators="+data.generators.Count(g=>seen.Contains(g.id))+" upgrades="+data.upgrades.Count(g=>seen.Contains(g.id))+" research="+data.research.Count(g=>seen.Contains(g.id))+" achievements="+s.S.achievements.Count);File.WriteAllText(Path.Combine(root,"Logs/content-reachability.json"),JsonSerializer.Serialize(new{generators=data.generators.Count(g=>seen.Contains(g.id)),upgrades=data.upgrades.Count(g=>seen.Contains(g.id)),research=data.research.Count(g=>seen.Contains(g.id)),achievements=s.S.achievements.Count,stories=s.S.discoveredStories.Count}));Console.WriteLine("POLICY firstPrestigeSeconds="+first+" second="+second+" third="+third);File.WriteAllText(Path.Combine(root,"Logs/balance-result.json"),JsonSerializer.Serialize(new{strategy="Every minute: prioritize missing processes; pause consumers of their cost currency; spend quarter Max on other upstream processes; buy affordable research/upgrades; first Stellar and Galactic reset, then repeat Genesis",firstPrestigeSeconds=first,secondPrestigeSeconds=second,thirdPrestigeSeconds=third,targetFirst=first>=3600&&first<=7200,targetSecond=second>=43200&&second<=86400,targetThird=third>=259200&&third<=604800}));}
}
















